#include <vector>
#include <deque>
#include <numeric>

class Solution {
public:
    long long maxScore(int n, std::vector<std::vector<int>>& edges) {
        std::vector<std::vector<int>> graph(n);
        for (const auto& e : edges) {
            graph[e[0]].push_back(e[1]);
            graph[e[1]].push_back(e[0]);
        }

        std::vector<bool> seen(n, false);
        std::vector<int> cycle_sizes;
        std::vector<int> path_sizes;

        for (int i = 0; i < n; ++i) {
            if (seen[i]) continue;
            std::vector<int> comp = {i};
            seen[i] = true;
            for (size_t idx = 0; idx < comp.size(); ++idx) {
                int u = comp[idx];
                for (int v : graph[u]) {
                    if (!seen[v]) {
                        seen[v] = true;
                        comp.push_back(v);
                    }
                }
            }

            bool is_cycle = true;
            for (int u : comp) {
                if (graph[u].size() != 2) {
                    is_cycle = false;
                    break;
                }
            }

            if (is_cycle) {
                cycle_sizes.push_back(comp.size());
            } else if (comp.size() > 1) {
                path_sizes.push_back(comp.size());
            }
        }

        long long ans = 0;
        int rem_n = n;

        for (int sz : cycle_sizes) {
            int left = rem_n - sz + 1, right = rem_n;
            std::deque<int> w = {right, right};
            long long score = 0;
            for (int val = right - 1; val >= left; --val) {
                int fv = w.front();
                w.pop_front();
                score += 1LL * fv * val;
                w.push_back(val);
            }
            ans += score + 1LL * w[0] * w[1];
            rem_n -= sz;
        }

        for (int sz : path_sizes) {
            int left = rem_n - sz + 1, right = rem_n;
            std::deque<int> w = {right, right};
            long long score = 0;
            for (int val = right - 1; val >= left; --val) {
                int fv = w.front();
                w.pop_front();
                score += 1LL * fv * val;
                w.push_back(val);
            }
            ans += score;
            rem_n -= sz;
        }

        return ans;
    }
};

import java.util.*;

class Solution {
    public long maxScore(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; ++i) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        boolean[] seen = new boolean[n];
        List<Integer> cycleSizes = new ArrayList<>();
        List<Integer> pathSizes = new ArrayList<>();

        for (int i = 0; i < n; ++i) {
            if (seen[i]) continue;
            List<Integer> comp = new ArrayList<>();
            comp.add(i);
            seen[i] = true;
            for (int idx = 0; idx < comp.size(); ++idx) {
                int u = comp.get(idx);
                for (int v : graph[u]) {
                    if (!seen[v]) {
                        seen[v] = true;
                        comp.add(v);
                    }
                }
            }

            boolean isCycle = true;
            for (int u : comp) {
                if (graph[u].size() != 2) {
                    isCycle = false;
                    break;
                }
            }

            if (isCycle) {
                cycleSizes.add(comp.size());
            } else if (comp.size() > 1) {
                pathSizes.add(comp.size());
            }
        }

        long ans = 0;
        int remN = n;

        for (int sz : cycleSizes) {
            int left = remN - sz + 1, right = remN;
            Deque<Integer> w = new ArrayDeque<>();
            w.add(right);
            w.add(right);
            long score = 0;
            for (int val = right - 1; val >= left; --val) {
                int fv = w.pollFirst();
                score += (long) fv * val;
                w.addLast(val);
            }
            int first = w.pollFirst();
            int second = w.pollFirst();
            ans += score + (long) first * second;
            remN -= sz;
        }

        for (int sz : pathSizes) {
            int left = remN - sz + 1, right = remN;
            Deque<Integer> w = new ArrayDeque<>();
            w.add(right);
            w.add(right);
            long score = 0;
            for (int val = right - 1; val >= left; --val) {
                int fv = w.pollFirst();
                score += (long) fv * val;
                w.addLast(val);
            }
            ans += score;
            remN -= sz;
        }

        return ans;
    }
}

/**
 * @param {number} n
 * @param {number[][]} edges
 * @return {number}
 */
var maxScore = function(n, edges) {
    const graph = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        graph[u].push(v);
        graph[v].push(u);
    }

    const seen = new Array(n).fill(false);
    const cycleSizes = [];
    const pathSizes = [];

    for (let i = 0; i < n; ++i) {
        if (seen[i]) continue;
        const comp = [i];
        seen[i] = true;
        for (let idx = 0; idx < comp.length; ++idx) {
            const u = comp[idx];
            for (const v of graph[u]) {
                if (!seen[v]) {
                    seen[v] = true;
                    comp.push(v);
                }
            }
        }

        let isCycle = true;
        for (const u of comp) {
            if (graph[u].length !== 2) {
                isCycle = false;
                break;
            }
        }

        if (isCycle) {
            cycleSizes.push(comp.length);
        } else if (comp.length > 1) {
            pathSizes.push(comp.length);
        }
    }

    let ans = 0;
    let remN = n;

    for (const sz of cycleSizes) {
        const left = remN - sz + 1, right = remN;
        const w = [right, right];
        let score = 0;
        for (let val = right - 1; val >= left; --val) {
            const fv = w.shift();
            score += fv * val;
            w.push(val);
        }
        ans += score + w[0] * w[1];
        remN -= sz;
    }

    for (const sz of pathSizes) {
        const left = remN - sz + 1, right = remN;
        const w = [right, right];
        let score = 0;
        for (let val = right - 1; val >= left; --val) {
            const fv = w.shift();
            score += fv * val;
            w.push(val);
        }
        ans += score;
        remN -= sz;
    }

    return ans;
};
